# Apply human-readable names from names.csv (generated by
# unpack/analysis/metag_name_functions.py) to the functions in Ghidra.
# @category metag
# @menupath Tools.Metag.Apply names from CSV
#
# names.csv columns: offset,name,evidence
#   s_<string>  named after a behaviour-tied string it references
#   copy/fill/lock/jtbl/scan/...  fingerprint category (heuristic hint)
# Offsets are file offsets == Ghidra addresses (image base 0). Safe to re-run.
# Run after metag_seed_functions.py + metag_string_xrefs.py for best coverage.
import csv
from ghidra.program.model.symbol import SourceType

f = askFile("Select names.csv", "Open")
rows = list(csv.DictReader(open(f.getAbsolutePath())))
monitor.initialize(len(rows))
ren = 0; made = 0; skip = 0
for row in rows:
    if monitor.isCancelled(): break
    monitor.incrementProgress(1)
    o = row.get('offset'); nm = row.get('name')
    if not o or not nm: continue
    try: a = toAddr(int(o, 16))
    except: continue
    fn = getFunctionAt(a)
    if fn is None:
        if getInstructionAt(a) is None:
            try: disassemble(a)
            except: pass
        try: fn = createFunction(a, None)
        except: fn = None
        if fn is not None: made += 1
    if fn is None: skip += 1; continue
    try:
        fn.setName(nm, SourceType.USER_DEFINED); ren += 1
    except:
        try: fn.setName(nm + '_' + o[2:], SourceType.USER_DEFINED); ren += 1
        except: skip += 1
println("named %d functions (%d newly created), skipped %d" % (ren, made, skip))
